#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Paths
const sourceFile = path.join(__dirname, 'product_master.json');
const womenOutputFile = path.join(__dirname, 'women_clothing.json');
const menOutputFile = path.join(__dirname, 'men_clothing.json');

console.log('Reading source file:', sourceFile);

// Read and parse the source file
const rawData = fs.readFileSync(sourceFile, 'utf8');
const products = JSON.parse(rawData);

console.log(`Total products: ${products.length}`);

// Filter products by category
const womenProducts = products.filter(product => product.category === 'women_clothing');
const menProducts = products.filter(product => product.category === 'men_clothing');

console.log(`Women's products: ${womenProducts.length}`);
console.log(`Men's products: ${menProducts.length}`);

// Write the separated files with 2-space indentation
fs.writeFileSync(womenOutputFile, JSON.stringify(womenProducts, null, 2), 'utf8');
fs.writeFileSync(menOutputFile, JSON.stringify(menProducts, null, 2), 'utf8');

console.log('\n✓ Successfully wrote:', womenOutputFile);
console.log('✓ Successfully wrote:', menOutputFile);

// Validation
const totalProcessed = womenProducts.length + menProducts.length;
if (totalProcessed === products.length) {
  console.log(`\n✓ Validation passed: ${totalProcessed} total products processed`);
} else {
  console.error(`\n✗ Validation failed: Expected ${products.length}, processed ${totalProcessed}`);
  process.exit(1);
}

